$ErrorActionPreference='Stop'
$root=Join-Path ([IO.Path]::GetTempPath()) ('repato-negative-validation-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $root|Out-Null
try {
 Import-Module (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Force
 Import-Module (Join-Path $PSScriptRoot 'Repato.AgentOrchestration.psm1') -Force
 $task='task-negative';$wf='workflow-negative';$commit='A'*40;$hash='B'*64;$build='build-negative';$qa='create-plan-views-v1';$test=$qa
 Initialize-RepatoTaskStore $root|Out-Null;New-RepatoTask $root $task 'synthetic' 'synthetic' 'qa/maya-qa-workflow' 'maya'|Out-Null
 Invoke-RepatoStoreMutation $root {param($d,$p)$t=Find-RepatoTask $d $task;$t|Add-Member NoteProperty deploymentWorkflows ([object[]]@([pscustomobject]@{workflowId=$wf;taskId=$task;qaBuildEvidence=[pscustomobject]@{BuildRequestId=$build;CandidateSourceCommit=$commit;ArtifactSha256=$hash;DeploymentValidation=$false;ManifestIntegrityValidation=$false}})) -Force;$t}
 $rev=[long](Find-RepatoTask (Read-RepatoTaskStore $root) $task).revision;$op=New-MayaQaDeploymentValidationOperation $root $task $wf $rev $build $commit $hash $qa $test
 $script:calls=0;$reason=$null
 try{Continue-MayaQaDeploymentValidation $root $task $wf $op.OperationId $op.ExpectedTaskRevision $build $commit $hash $qa $test -RequestInvoker {param($pending)$script:calls++;[pscustomobject]@{schemaVersion=1;operation='validate-qa-deployment';requestId=$pending.RequestId;succeeded=$false;validationIdentity='RAMSAI\RepatoQA';candidateCommit=$commit;qaWorkflowId=$qa;testId=$test;candidateSha256=$hash;isolationPassed=$true;qaAddinRoot='C:\Users\RepatoQA\AppData\Roaming\Autodesk\Revit\Addins\2025\RepatoQA';manifestIntegrityPassed=$false;errorCode='manifest-integrity-failed';errorMessage='runtime manifest mismatch'}}}catch{$reason=$_.Exception.Message}
 if($script:calls -ne 1 -or $reason -cne 'Runtime manifest integrity evidence rejected deployment.'){throw 'Matched negative response did not raise its exact semantic rejection.'}
 $stored=Find-RepatoTask (Read-RepatoTaskStore $root) $task;$failed=@($stored.deploymentValidationOperations|Where-Object OperationId -ceq $op.OperationId)[0]
 if($failed.RequestDisposition -cne 'completed-failed' -or $failed.ValidationStatus -cne 'failed' -or $failed.FailureReason -cne $reason -or !$failed.Response -or $failed.Response.requestId -cne $op.RequestId -or $failed.Response.errorCode -cne 'manifest-integrity-failed'){throw 'Matched negative response evidence was not durably retained.'}
 if($stored.mayaTaraAttempt -or $stored.mayaTaraExecution -or $stored.deploymentWorkflows[0].qaBuildEvidence.DeploymentValidation){throw 'Failed validation did not remain blocked from QA.'}
 try{Continue-MayaQaDeploymentValidation $root $task $wf $op.OperationId $op.ExpectedTaskRevision $build $commit $hash $qa $test -RequestInvoker {$script:calls++}}catch{};if($script:calls -ne 1){throw 'Terminal failed response was automatically retried.'}
 $rev=[long]$stored.revision;$mismatch=New-MayaQaDeploymentValidationOperation $root $task $wf $rev $build $commit $hash $qa $test;$script:mismatchCalls=0
 try{Continue-MayaQaDeploymentValidation $root $task $wf $mismatch.OperationId $mismatch.ExpectedTaskRevision $build $commit $hash $qa $test -RequestInvoker {param($pending)$script:mismatchCalls++;[pscustomobject]@{schemaVersion=1;operation='validate-qa-deployment';requestId=[guid]::NewGuid().ToString('N');succeeded=$false;validationIdentity='RAMSAI\RepatoQA';candidateCommit=$commit;qaWorkflowId=$qa;testId=$test;candidateSha256=$hash;isolationPassed=$true;qaAddinRoot='C:\Users\RepatoQA\AppData\Roaming\Autodesk\Revit\Addins\2025\RepatoQA';manifestIntegrityPassed=$false;errorCode='manifest-integrity-failed'}}}catch{}
 $stored=Find-RepatoTask (Read-RepatoTaskStore $root) $task;$ambiguous=@($stored.deploymentValidationOperations|Where-Object OperationId -ceq $mismatch.OperationId)[0]
 if($script:mismatchCalls -ne 1 -or $ambiguous.RequestDisposition -cne 'transmitting' -or $ambiguous.Response){throw 'Unmatched response did not remain ambiguous.'}
 try{Continue-MayaQaDeploymentValidation $root $task $wf $mismatch.OperationId $mismatch.ExpectedTaskRevision $build $commit $hash $qa $test -RequestInvoker {$script:mismatchCalls++}}catch{};if($script:mismatchCalls -ne 1){throw 'Ambiguous response was automatically retried.'}
 $ledger=Join-Path $root 'replay.json';@([pscustomobject]@{RequestId=$mismatch.RequestId;RunId=$mismatch.RequestId;PayloadHash='C'*64;SeenUtc=[DateTimeOffset]::UtcNow.ToString('o')})|ConvertTo-Json|Set-Content -LiteralPath $ledger
 $recovered=Fail-MayaQaBoundDeploymentValidationWithoutResponse $root $task $wf $mismatch.OperationId $mismatch.RequestId ([long]$stored.revision) 'Runtime manifest integrity evidence rejected deployment.' $ledger -RevitProcessProvider { @() } -Confirm:$false
 $stored=Find-RepatoTask (Read-RepatoTaskStore $root) $task;$terminal=@($stored.deploymentValidationOperations|Where-Object OperationId -ceq $mismatch.OperationId)[0]
 if($recovered.Status -cne 'FailedResponseUnavailable' -or $terminal.RequestDisposition -cne 'completed-failed' -or $terminal.Response -or !$terminal.FailureEvidence.LedgerReceipt -or $terminal.FailureEvidence.SuccessClaimed){throw 'Bound response-unavailable recovery did not preserve terminal failure evidence.'}
 [pscustomobject]@{MatchedNegativeTerminalFailure='PASS';ExactReasonAndResponseRetained='PASS';QaBlocked='PASS';UnmatchedResponseAmbiguous='PASS';NoAutomaticRetry='PASS';BoundResponseUnavailableRecovery='PASS';RevitLaunched=$false;RealStoreTouched=$false}|ConvertTo-Json -Compress
} finally {Remove-Item $root -Recurse -Force -ErrorAction SilentlyContinue}
